        assert(s1.len() + suffix.len() == s2.len() + suffix.len());
        assert(s1.len() == s2.len());
        assert forall|i: int| 0 <= i < s1.len() implies s1[i] == s2[i] by {
            assert(left[i] == right[i]);
            assert(left[i] == s1[i]);
            assert(right[i] == s2[i]);
        };
        assert(s1 =~= s2);
        assert(s1 == s2);
